__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"signalementDocument",{enumerable:!0,get:function(){return s}});var n=r(d[0]),t=r(d[1]);const s=(0,n.publishedDocument)({id:"signalement",slug:"signalement",title:"Signaler un contenu, un produit ou un \xe9tablissement",shortTitle:"Signaler",sections:[{heading:"1. Objet",paragraphs:[`${t.LEGAL_TRADE_NAME}, \xe9dit\xe9 par ${t.LEGAL_OPERATOR_NAME}, met \xe0 disposition un m\xe9canisme permettant de signaler un contenu, un produit, un \xe9tablissement ou une information susceptible d\u2019\xeatre illicite ou contraire aux r\xe8gles du Service.`,"Ce m\xe9canisme peut notamment \xeatre utilis\xe9 pour signaler une offre de produit potentiellement illicite ou dangereux, une fraude, une usurpation d\u2019identit\xe9, un contenu trompeur, une atteinte aux droits d\u2019un tiers ou tout autre contenu susceptible d\u2019\xeatre contraire au droit applicable.","Croki distingue les notifications portant sur un contenu potentiellement illicite des simples demandes de support, r\xe9clamations commerciales ou signalements concernant uniquement le respect des r\xe8gles internes du Service."]},{heading:"2. Qui peut signaler un contenu potentiellement illicite ?",paragraphs:["Toute personne physique ou toute entit\xe9 peut notifier \xe0 Croki la pr\xe9sence d\u2019un contenu qu\u2019elle consid\xe8re comme illicite.","Il n\u2019est pas n\xe9cessaire de disposer d\u2019un compte Croki ou d\u2019\xeatre connect\xe9 pour utiliser le m\xe9canisme public de notification de contenu potentiellement illicite.","Un Client, un Professionnel, un titulaire de droits, une association, une entreprise, une administration ou toute autre personne ou entit\xe9 peut ainsi effectuer un signalement lorsqu\u2019elle dispose des informations permettant d\u2019identifier le contenu concern\xe9."]},{heading:"3. Que peut-on signaler ?",paragraphs:["Le m\xe9canisme peut \xeatre utilis\xe9 lorsqu\u2019un \xe9l\xe9ment pr\xe9cis publi\xe9, propos\xe9 ou accessible sur Croki est consid\xe9r\xe9 comme potentiellement illicite."],bullets:["Un produit dont la commercialisation para\xeet interdite ou illicite.","Un produit ou une information pr\xe9sentant un risque grave ou manifestement trompeur pour le consommateur.","Un \xe9tablissement ou une offre susceptible d\u2019\xeatre frauduleux.","Une usurpation d\u2019identit\xe9 ou de qualit\xe9 professionnelle.","Une photographie, un texte, un logo ou un autre contenu portant potentiellement atteinte \xe0 des droits de propri\xe9t\xe9 intellectuelle.","Un contenu portant potentiellement atteinte \xe0 la vie priv\xe9e ou aux donn\xe9es personnelles d\u2019un tiers.","Un contenu comportant des menaces, du harc\xe8lement ou des propos susceptibles d\u2019\xeatre illicites.","Un contenu haineux, discriminatoire ou incitant potentiellement \xe0 la violence.","Une offre, description ou pr\xe9sentation susceptible de constituer une pratique commerciale illicite ou trompeuse.","Un faux avis ou une manipulation susceptible d\u2019enfreindre la l\xe9gislation applicable.","Tout autre contenu ou comportement dont le maintien sur Croki para\xeet contraire au droit de l\u2019Union europ\xe9enne ou au droit national applicable."]},{heading:"4. Signalement d\u2019un produit alimentaire",paragraphs:["Un produit alimentaire peut notamment \xeatre signal\xe9 lorsqu\u2019il para\xeet pr\xe9senter un risque pour la s\xe9curit\xe9 des consommateurs, comporter une information potentiellement trompeuse ou \xeatre propos\xe9 dans des conditions susceptibles d\u2019\xeatre contraires \xe0 la r\xe9glementation.","Le formulaire doit permettre d\u2019identifier pr\xe9cis\xe9ment le produit et l\u2019\xc9tablissement concern\xe9s.","Lorsqu\u2019un signalement fait appara\xeetre un risque potentiel s\xe9rieux pour la sant\xe9 ou la s\xe9curit\xe9 des personnes, Croki peut lui appliquer un niveau de priorit\xe9 sup\xe9rieur et prendre les mesures conservatoires raisonnablement n\xe9cessaires pendant son examen.","Le signalement \xe0 Croki ne remplace pas les d\xe9marches qu\u2019une personne peut effectuer directement aupr\xe8s des autorit\xe9s comp\xe9tentes lorsqu\u2019une situation l\u2019exige."]},{heading:"5. Signalement d\u2019un avis",paragraphs:["Un avis publi\xe9 sur Croki peut \xeatre signal\xe9 lorsqu\u2019il para\xeet comporter un contenu illicite ou contraire aux r\xe8gles du Service.","Le Professionnel concern\xe9 dispose \xe9galement d\u2019un m\xe9canisme sp\xe9cifique et gratuit lui permettant de signaler de mani\xe8re motiv\xe9e un doute sur l\u2019authenticit\xe9 d\u2019un avis.","Le simple fait qu\u2019un avis soit n\xe9gatif ou d\xe9favorable au Professionnel ne constitue pas, \xe0 lui seul, un motif permettant son retrait.","Les r\xe8gles sp\xe9cifiques aux avis sont d\xe9crites dans la Politique des avis clients."]},{heading:"6. Signalement d\u2019une violation des r\xe8gles Croki",paragraphs:["Certains comportements peuvent \xeatre contraires aux CGU ou aux Conditions Pro sans constituer n\xe9cessairement un contenu illicite au sens de la loi.","Croki peut proposer dans l\u2019application des m\xe9canismes distincts permettant aux utilisateurs connect\xe9s de signaler ce type de probl\xe8me.","Une violation des r\xe8gles Croki peut notamment concerner un contenu manifestement hors sujet, un comportement abusif, une utilisation frauduleuse d\u2019une fonctionnalit\xe9 ou une tentative de manipulation du Service.","Le m\xe9canisme public de notification de contenu potentiellement illicite reste accessible ind\xe9pendamment de ces m\xe9canismes internes."]},{heading:"7. Informations n\xe9cessaires au signalement",paragraphs:["Pour permettre \xe0 Croki de prendre une d\xe9cision \xe9clair\xe9e et diligente, le signalement doit identifier suffisamment pr\xe9cis\xe9ment le contenu concern\xe9 et expliquer pourquoi il est consid\xe9r\xe9 comme potentiellement illicite.","Aucune connaissance juridique particuli\xe8re n\u2019est exig\xe9e : il est possible de d\xe9crire simplement les faits et les raisons du signalement."],bullets:["Le type de contenu concern\xe9 : \xe9tablissement, produit, avis, r\xe9ponse, photographie ou autre contenu.","L\u2019emplacement \xe9lectronique exact du contenu, par exemple son URL ou son identifiant Croki lorsqu\u2019il est disponible.","Les informations compl\xe9mentaires n\xe9cessaires pour retrouver pr\xe9cis\xe9ment le contenu lorsqu\u2019une URL ne suffit pas.","Une explication suffisamment pr\xe9cise des raisons pour lesquelles le contenu est consid\xe9r\xe9 comme potentiellement illicite.","Les \xe9l\xe9ments factuels utiles permettant de comprendre le signalement.","Le nom et l\u2019adresse \xe9lectronique de la personne ou de l\u2019entit\xe9 effectuant la notification lorsque ces informations sont requises.","Une d\xe9claration confirmant que la personne effectuant le signalement estime de bonne foi que les informations et affirmations communiqu\xe9es sont exactes et compl\xe8tes."]},{heading:"8. Identification de la personne qui signale",paragraphs:["Aucun compte Croki n\u2019est n\xe9cessaire pour effectuer une notification de contenu potentiellement illicite.","Le formulaire demande normalement le nom et une adresse \xe9lectronique permettant \xe0 Croki d\u2019accuser r\xe9ception du signalement et de communiquer sa d\xe9cision.","Les exceptions pr\xe9vues par la r\xe9glementation concernant certaines cat\xe9gories particuli\xe8rement sensibles de contenus restent applicables lorsque l\u2019identit\xe9 ou les coordonn\xe9es du d\xe9clarant ne doivent pas \xeatre exig\xe9es.","Croki ne doit pas imposer la cr\xe9ation d\u2019un compte comme condition suppl\xe9mentaire pour exercer le droit de notification."]},{heading:"9. Localisation pr\xe9cise du contenu",paragraphs:["Le signalement doit permettre \xe0 Croki de retrouver exactement l\u2019\xe9l\xe9ment concern\xe9.","Lorsque le formulaire est ouvert directement depuis un produit, un avis, un \xe9tablissement ou un autre contenu Croki, son identifiant ou son emplacement peut \xeatre renseign\xe9 automatiquement.","Lorsque le signalement est effectu\xe9 depuis la page publique, la personne est invit\xe9e \xe0 fournir l\u2019URL exacte ou les informations permettant d\u2019identifier sans ambigu\xeft\xe9 le contenu.","Un signalement g\xe9n\xe9ral ne permettant pas d\u2019identifier le contenu concern\xe9 peut n\xe9cessiter des informations compl\xe9mentaires avant de pouvoir \xeatre examin\xe9."]},{heading:"10. Pi\xe8ces et informations compl\xe9mentaires",paragraphs:["La personne effectuant un signalement peut fournir des informations compl\xe9mentaires utiles lorsqu\u2019elles sont n\xe9cessaires pour comprendre la situation.","Croki demande de ne pas transmettre de document d\u2019identit\xe9, de donn\xe9e de sant\xe9, de donn\xe9e bancaire ou d\u2019autre information sensible lorsqu\u2019elle n\u2019est pas n\xe9cessaire au traitement du signalement.","Lorsqu\u2019une preuve comporte des donn\xe9es relatives \xe0 des tiers, seules les informations n\xe9cessaires au signalement doivent \xeatre communiqu\xe9es."]},{heading:"11. D\xe9claration de bonne foi",paragraphs:["Avant l\u2019envoi, la personne effectuant une notification confirme qu\u2019elle estime de bonne foi que les informations et affirmations contenues dans son signalement sont exactes et compl\xe8tes.","Cette d\xe9claration ne signifie pas que la personne doit \xeatre certaine de la qualification juridique d\xe9finitive du contenu.","Croki reste responsable de l\u2019examen du signalement et de la d\xe9cision qu\u2019il convient de prendre au regard des informations disponibles."]},{heading:"12. Accus\xe9 de r\xe9ception",paragraphs:["Lorsque Croki dispose d\u2019une adresse \xe9lectronique permettant de contacter la personne ou l\u2019entit\xe9 ayant soumis le signalement, un accus\xe9 de r\xe9ception est envoy\xe9 dans les meilleurs d\xe9lais.","Cet accus\xe9 de r\xe9ception confirme que le signalement a \xe9t\xe9 re\xe7u ; il ne signifie pas que Croki consid\xe8re d\xe9j\xe0 le contenu comme illicite.","Une r\xe9f\xe9rence de signalement peut \xeatre communiqu\xe9e afin de permettre son suivi."]},{heading:"13. Examen du signalement",paragraphs:["Croki examine les notifications de contenu potentiellement illicite en temps utile, avec diligence, objectivit\xe9 et sans d\xe9cision arbitraire.","L\u2019examen porte notamment sur le contenu identifi\xe9, les motifs du signalement, les informations disponibles dans Croki et, lorsque cela est n\xe9cessaire, les r\xe8gles l\xe9gales ou contractuelles applicables.","La rapidit\xe9 du traitement peut \xeatre adapt\xe9e \xe0 la nature et \xe0 l\u2019urgence du contenu signal\xe9.","Un contenu susceptible d\u2019impliquer un risque grave pour la vie ou la s\xe9curit\xe9 d\u2019une personne peut notamment n\xe9cessiter un traitement particuli\xe8rement rapide."]},{heading:"14. Demande d\u2019informations compl\xe9mentaires",paragraphs:["Lorsque les informations communiqu\xe9es ne permettent pas d\u2019identifier suffisamment le contenu ou de comprendre le motif du signalement, Croki peut demander des pr\xe9cisions \xe0 la personne ayant effectu\xe9 la notification.","Le signalement n\u2019est pas automatiquement consid\xe9r\xe9 comme infond\xe9 au seul motif qu\u2019une information compl\xe9mentaire est n\xe9cessaire.","Lorsque Croki ne dispose d\u2019aucun moyen de contacter l\u2019auteur du signalement, la d\xe9cision est prise \xe0 partir des informations effectivement disponibles."]},{heading:"15. D\xe9cisions possibles",paragraphs:["Apr\xe8s examen, Croki peut notamment d\xe9cider :"],bullets:["de ne prendre aucune mesure lorsque les informations disponibles ne justifient pas une restriction ;","de demander au Professionnel ou \xe0 l\u2019auteur du contenu de corriger ou compl\xe9ter une information ;","de limiter temporairement la visibilit\xe9 du contenu pendant une v\xe9rification lorsque cela est justifi\xe9 ;","de masquer ou retirer un contenu ;","de retirer ou rendre indisponible un produit ;","de suspendre temporairement une fonctionnalit\xe9 ;","de restreindre ou suspendre un \xc9tablissement ;","de prendre une mesure \xe0 l\u2019\xe9gard d\u2019un compte lorsque les conditions applicables sont r\xe9unies ;","de transmettre des informations aux autorit\xe9s comp\xe9tentes lorsqu\u2019une obligation l\xe9gale l\u2019impose."]},{heading:"16. Proportionnalit\xe9",paragraphs:["Une mesure de mod\xe9ration doit \xeatre adapt\xe9e \xe0 la nature et \xe0 la gravit\xe9 de la situation.","Lorsque la suppression d\u2019un contenu d\xe9termin\xe9 suffit \xe0 traiter le probl\xe8me, Croki n\u2019a pas vocation \xe0 suspendre automatiquement l\u2019int\xe9gralit\xe9 d\u2019un compte ou d\u2019un \xc9tablissement.","Croki tient compte des droits et int\xe9r\xeats des personnes concern\xe9es, notamment de la libert\xe9 d\u2019expression, des droits des consommateurs, de la s\xe9curit\xe9 et des droits des tiers.","Une notification ne provoque donc pas automatiquement la suppression du contenu signal\xe9."]},{heading:"17. Information de la personne ayant signal\xe9",paragraphs:["Lorsque Croki dispose des coordonn\xe9es \xe9lectroniques du d\xe9clarant, celui-ci est inform\xe9 dans les meilleurs d\xe9lais de la d\xe9cision prise concernant le contenu signal\xe9.","L\u2019information indique notamment si Croki a d\xe9cid\xe9 d\u2019agir ou de ne pas agir sur le contenu.","Elle comporte \xe9galement les informations appropri\xe9es concernant les possibilit\xe9s de contestation ou de recours disponibles au regard de la d\xe9cision concern\xe9e.","La d\xe9cision communiqu\xe9e ne r\xe9v\xe8le pas les donn\xe9es confidentielles ou personnelles d\u2019autres utilisateurs qui ne sont pas n\xe9cessaires \xe0 cette information."]},{heading:"18. Information de l\u2019auteur du contenu",paragraphs:["Lorsqu\u2019un contenu fourni par un utilisateur ou un Professionnel est supprim\xe9, rendu inaccessible ou fait l\u2019objet d\u2019une autre restriction parce qu\u2019il est consid\xe9r\xe9 comme illicite ou contraire aux Conditions applicables, Croki fournit \xe0 la personne concern\xe9e un expos\xe9 clair et suffisamment pr\xe9cis des motifs lorsque la r\xe9glementation l\u2019exige.","Cet expos\xe9 peut notamment indiquer la nature de la mesure, les faits et circonstances ayant conduit \xe0 la d\xe9cision, la r\xe9f\xe9rence aux r\xe8gles concern\xe9es et les possibilit\xe9s de contestation disponibles.","L\u2019identit\xe9 de la personne ayant effectu\xe9 le signalement n\u2019est pas communiqu\xe9e syst\xe9matiquement \xe0 l\u2019auteur du contenu.","Elle ne peut \xeatre communiqu\xe9e que lorsque cette information est l\xe9galement justifi\xe9e et n\xe9cessaire au traitement de la situation."]},{heading:"19. Intervention humaine et automatisation",paragraphs:["Croki peut utiliser des m\xe9canismes techniques pour organiser, d\xe9tecter ou prioriser certains signalements, notamment pour la s\xe9curit\xe9 et la pr\xe9vention des abus.","Lorsque des moyens automatis\xe9s sont utilis\xe9s pour traiter une notification ou contribuer directement \xe0 une d\xe9cision, l\u2019information fournie au d\xe9clarant en fait \xe9tat lorsque la r\xe9glementation l\u2019exige.","Les d\xe9cisions susceptibles d\u2019avoir des cons\xe9quences importantes font l\u2019objet des contr\xf4les appropri\xe9s afin d\u2019\xe9viter qu\u2019une mesure injustifi\xe9e soit prise uniquement en raison d\u2019un signal automatis\xe9."]},{heading:"20. Signalements urgents",paragraphs:["Les signalements indiquant un risque imm\xe9diat ou s\xe9rieux pour la vie, la s\xe9curit\xe9 ou la sant\xe9 d\u2019une personne font l\u2019objet d\u2019une attention prioritaire.","Le formulaire Croki n\u2019est pas un service d\u2019urgence et ne doit pas retarder le recours aux autorit\xe9s ou services d\u2019urgence comp\xe9tents lorsque la situation n\xe9cessite une intervention imm\xe9diate."]},{heading:"21. Infractions p\xe9nales mena\xe7ant la vie ou la s\xe9curit\xe9",paragraphs:["Lorsque FOODTECH SOLUTIONS prend connaissance d\u2019informations donnant lieu \xe0 un soup\xe7on qu\u2019une infraction p\xe9nale impliquant une menace pour la vie ou la s\xe9curit\xe9 d\u2019une ou plusieurs personnes a \xe9t\xe9 commise, est en cours ou est susceptible d\u2019\xeatre commise, elle informe les autorit\xe9s r\xe9pressives ou judiciaires comp\xe9tentes lorsque le Digital Services Act l\u2019exige.","FOODTECH SOLUTIONS peut alors communiquer aux autorit\xe9s les informations pertinentes dont elle dispose conform\xe9ment aux obligations l\xe9gales applicables.","Cette obligation est distincte du traitement ordinaire des signalements et ne signifie pas que chaque signalement Croki est automatiquement transmis \xe0 une autorit\xe9."]},{heading:"22. Absence de transmission automatique g\xe9n\xe9rale",paragraphs:["Un signalement ordinaire n\u2019est pas automatiquement transmis \xe0 la CNIL, \xe0 la DGCCRF, \xe0 l\u2019Arcom, \xe0 une autorit\xe9 judiciaire ou \xe0 un service de police du seul fait de son d\xe9p\xf4t.","FOODTECH SOLUTIONS peut toutefois effectuer une transmission lorsqu\u2019une obligation l\xe9gale, une d\xe9cision d\u2019autorit\xe9, la nature d\u2019une infraction ou la protection des personnes l\u2019exige.","La personne ayant effectu\xe9 le signalement reste libre d\u2019effectuer elle-m\xeame les d\xe9marches qu\u2019elle estime n\xe9cessaires aupr\xe8s des autorit\xe9s comp\xe9tentes."]},{heading:"23. Produits retir\xe9s ou bloqu\xe9s",paragraphs:["Lorsqu\u2019un produit est retir\xe9 ou rendu inaccessible \xe0 la suite d\u2019un signalement, cette mesure peut \xeatre limit\xe9e au produit concern\xe9 lorsque cela suffit \xe0 traiter le risque identifi\xe9.","Lorsque la situation affecte plus largement l\u2019activit\xe9 ou la s\xe9curit\xe9 d\u2019un \xc9tablissement, Croki peut prendre des mesures suppl\xe9mentaires conform\xe9ment aux Conditions Pro et aux obligations l\xe9gales applicables.","Le Professionnel demeure responsable de ses propres obligations relatives notamment \xe0 la s\xe9curit\xe9 alimentaire, aux retraits ou rappels de produits et aux relations avec les autorit\xe9s comp\xe9tentes."]},{heading:"24. Contestation d\u2019une d\xe9cision",paragraphs:["Une personne affect\xe9e par une d\xe9cision de mod\xe9ration peut demander son r\xe9examen au moyen des m\xe9canismes de support ou de contestation disponibles dans Croki.","Lorsque des voies de recours sp\xe9cifiques sont impos\xe9es par la r\xe9glementation applicable \xe0 FOODTECH SOLUTIONS, elles sont communiqu\xe9es avec la d\xe9cision concern\xe9e.","La contestation est examin\xe9e ind\xe9pendamment du simple fait qu\u2019un signalement initial ait conduit \xe0 la mesure.","La possibilit\xe9 de demander un r\xe9examen \xe0 Croki ne prive pas une personne de son droit de saisir une juridiction ou une autorit\xe9 comp\xe9tente lorsqu\u2019elle en dispose."]},{heading:"25. Signalements manifestement abusifs",paragraphs:["Le m\xe9canisme de signalement doit \xeatre utilis\xe9 de bonne foi.","Croki peut prendre des mesures proportionn\xe9es afin de prot\xe9ger le Service contre les signalements manifestement mensongers, frauduleux, harcelants, automatis\xe9s de mani\xe8re abusive ou utilis\xe9s dans le seul objectif de nuire \xe0 un tiers.","Une erreur, un doute raisonnable ou le rejet d\u2019un signalement ne suffit pas, \xe0 lui seul, \xe0 caract\xe9riser un abus.","Toute mesure contre un utilisateur en raison de signalements abusifs tient compte notamment du nombre, de la gravit\xe9, de la fr\xe9quence et du caract\xe8re manifeste des abus constat\xe9s."]},{heading:"26. Protection de la personne qui signale",paragraphs:["Les informations personnelles de la personne ayant effectu\xe9 une notification sont trait\xe9es uniquement dans la mesure n\xe9cessaire au traitement du signalement, au respect des obligations l\xe9gales et \xe0 la d\xe9fense des droits des personnes concern\xe9es.","Croki ne rend pas publiquement l\u2019identit\xe9 du d\xe9clarant.","L\u2019identit\xe9 du d\xe9clarant n\u2019est pas communiqu\xe9e automatiquement au Professionnel ou \xe0 l\u2019auteur du contenu signal\xe9.","Les conditions de traitement et de conservation de ces donn\xe9es sont d\xe9taill\xe9es dans la Politique de confidentialit\xe9."]},{heading:"27. Donn\xe9es personnelles",paragraphs:["Le traitement d\u2019un signalement peut n\xe9cessiter la collecte des coordonn\xe9es du d\xe9clarant, du motif, du contenu concern\xe9, des informations ou preuves communiqu\xe9es, du statut du dossier, des d\xe9cisions prises et des \xe9changes li\xe9s au signalement.","Ces informations sont utilis\xe9es pour recevoir, examiner, documenter et traiter le signalement, assurer la s\xe9curit\xe9 du Service, respecter les obligations l\xe9gales et permettre la d\xe9fense des droits.","Les donn\xe9es ne sont conserv\xe9es que pendant la dur\xe9e n\xe9cessaire \xe0 ces finalit\xe9s et conform\xe9ment \xe0 la Politique de confidentialit\xe9."]},{heading:"28. Tra\xe7abilit\xe9 des d\xe9cisions",paragraphs:["Croki conserve une trace appropri\xe9e des signalements et d\xe9cisions n\xe9cessaires \xe0 la s\xe9curit\xe9, \xe0 la preuve du traitement, \xe0 la gestion des contestations et au respect de ses obligations r\xe9glementaires.","Cette tra\xe7abilit\xe9 peut notamment comprendre la date du signalement, le contenu ou identifiant concern\xe9, le motif communiqu\xe9, l\u2019\xe9tat du dossier, la d\xe9cision et son motif.","Les acc\xe8s aux informations non publiques relatives aux signalements sont limit\xe9s aux personnes habilit\xe9es."]},{heading:"29. Signaleurs de confiance",paragraphs:["Le Digital Services Act pr\xe9voit un statut particulier de \xab signaleur de confiance \xbb attribu\xe9 par les coordinateurs pour les services num\xe9riques aux entit\xe9s remplissant les conditions r\xe9glementaires.","Lorsque les obligations correspondantes sont applicables \xe0 FOODTECH SOLUTIONS, les notifications provenant de signaleurs de confiance officiellement d\xe9sign\xe9s sont trait\xe9es avec la priorit\xe9 pr\xe9vue par la r\xe9glementation.","Le statut de signaleur de confiance ne signifie pas que Croki doit accepter automatiquement toute demande de retrait : Croki reste responsable de la d\xe9cision prise sur le contenu signal\xe9."]},{heading:"30. Accessibilit\xe9 du m\xe9canisme",paragraphs:["Le m\xe9canisme de notification de Croki est con\xe7u pour \xeatre facilement identifiable, accessible et utilisable.","Lorsqu\u2019un bouton de signalement peut raisonnablement \xeatre plac\xe9 \xe0 proximit\xe9 d\u2019un contenu, Croki cherche \xe0 permettre l\u2019ouverture du formulaire depuis ce contenu afin d\u2019en renseigner automatiquement l\u2019identifiant.","Une page publique de signalement reste disponible afin qu\u2019une personne puisse effectuer une notification sans disposer d\u2019un compte Croki."]},{heading:"31. \xc9volution du m\xe9canisme",paragraphs:["Croki peut faire \xe9voluer son m\xe9canisme de signalement afin d\u2019am\xe9liorer son accessibilit\xe9, sa s\xe9curit\xe9 ou sa conformit\xe9 r\xe9glementaire.","Toute \xe9volution doit pr\xe9server la possibilit\xe9 d\u2019effectuer facilement une notification suffisamment pr\xe9cise d\u2019un contenu potentiellement illicite.","Le m\xe9canisme ne doit pas \xeatre con\xe7u de mani\xe8re \xe0 d\xe9courager artificiellement ou rendre excessivement complexe un signalement l\xe9gitime.","La pr\xe9sente page est mise \xe0 jour lorsque le fonctionnement du m\xe9canisme change de mani\xe8re substantielle."]},{heading:"32. Contact",paragraphs:[`Responsable du Service : ${t.LEGAL_OPERATOR_NAME}.`,`Service : ${t.LEGAL_TRADE_NAME}.`,`Adresse : ${t.LEGAL_SLOT.registeredOffice}.`,`E-mail : ${t.LEGAL_SLOT.email}.`,`T\xe9l\xe9phone : ${t.LEGAL_SLOT.phone}.`]}]})},1535,[1630,1228]);